"use client";

import React, { useState } from "react";
import Link from "next/link";
import { Menu, X } from "lucide-react";

const NavBar = () => {
  const [menuOpen, setMenuOpen] = useState(false);

  const navItems = [
    { label: "// home", href: "/" },
    { label: "// about", href: "/about" },
    { label: "// education", href: "/education" },
    { label: "// skills", href: "/skills" },
    { label: "// projects", href: "projects" },
    { label: "// contact", href: "/contact" },
  ];

  return (
    <nav className="w-full fixed top-0 z-50 bg-transparent">
      <div className="flex justify-between items-center py-4 px-6">
        <div className="text-white text-2xl font-mono">Ryan Stoffel</div>
        <button
          className="sm:hidden text-white"
          onClick={() => setMenuOpen(!menuOpen)}
        >
          {menuOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
        <div className="hidden sm:flex gap-6">
          {navItems.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              className="text-white text-lg font-mono"
            >
              {item.label}
            </Link>
          ))}
        </div>
      </div>
      {/* Mobile Dropdown Menu */}
      {menuOpen && (
        <div className="sm:hidden flex flex-col items-center bg-black bg-opacity-90 py-4">
          {navItems.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              className="text-white text-lg font-mono py-2"
              onClick={() => setMenuOpen(false)}
            >
              {item.label}
            </Link>
          ))}
        </div>
      )}
    </nav>
  );
};

export default NavBar;
